inline const Property* Find(std::string_view name){
  std::size_t first=0,last=kAliases.size();
  while(first<last){const auto middle=first+(last-first)/2;if(kAliases[middle].name<name)first=middle+1;else last=middle;}
  return first<kAliases.size()&&kAliases[first].name==name?&kProperties[kAliases[first].property]:nullptr;
}
